WITH supplier_totals AS (SELECT supplier_id, MIN(launch_date) min_launch_date, ROUND((100 * SUM(CASE WHEN category = 'Grocery' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_grocery FROM products GROUP BY supplier_id) SELECT suppliers.id, suppliers.rating, suppliers.country, supplier_totals.min_launch_date, supplier_totals.pct_grocery FROM suppliers LEFT JOIN supplier_totals ON suppliers.id = supplier_totals.supplier_id WHERE supplier_totals.pct_grocery > 77 ORDER BY min_launch_date;
